import {renderResultLocations} from './render-model.mjs';
export function mountRenderMonitor({host,node,button,tr,exportFiles,onPause,onStop}){
 const section=node('section'),content=node('div'),heading=node('h3'),state=node('p'),timing=node('p'),stage=node('p'),progress=node('progress'),connection=node('p'),media=node('div'),reference=node('img'),picture=node('img'),clip=node('video'),empty=node('p'),originalLabel=node('p'),previewLabel=node('p'),originalBox=node('div'),previewBox=node('div'),tools=node('div'),graph=node('details'),graphTitle=node('summary'),graphNodes=node('div'),prompt=node('details'),promptTitle=node('summary'),promptText=node('pre'),dialog=node('dialog'),saved=node('p'),saveVideo=node('a'),float=button('',()=>{section.scrollIntoView({behavior:'smooth',block:'start'});});
 section.id='renderLive';section.className='render-monitor';section.hidden=true;dialog.id='renderLiveDialog';dialog.className='render-monitor-dialog';media.className='render-monitor-media';tools.className='toolbar';timing.className=connection.className='muted';originalBox.className=previewBox.className='render-monitor-picture';graphNodes.className='render-monitor-graph';promptText.className='render-prompt-preview';float.className='render-live-jump';float.hidden=true;
 reference.alt='';picture.alt='';clip.muted=true;clip.autoplay=true;clip.loop=true;clip.controls=true;clip.playsInline=true;clip.preload='none';picture.hidden=clip.hidden=true;
 originalBox.append(originalLabel,reference);previewBox.append(previewLabel,picture,clip,empty);media.append(originalBox,previewBox);
 const large=button('',()=>{if(dialog.open)return;dialog.append(content);dialog.showModal();}),close=button('',()=>dialog.close()),download=button('',()=>void exportFiles(currentJob?.shotId)),pause=button('',onPause),stop=button('',onStop,'danger');tools.append(large,download,pause,stop);dialog.append(close);dialog.onclose=()=>section.prepend(content);
 graph.append(graphTitle,graphNodes);prompt.append(promptTitle,promptText);content.append(heading,state,timing,stage,progress,connection,media,saved,saveVideo,tools,prompt,graph);section.append(content);host.append(section,dialog,float);
 let currentRun=null,currentJob=null,mediaKey='',workflowKey='',workflow=null;
 graph.ontoggle=()=>{if(graph.open&&currentJob)void workflowDetails();};prompt.ontoggle=()=>{if(prompt.open&&currentJob)void workflowDetails();};
 async function workflowDetails(){const key=currentRun.id+currentJob.shotId;if(workflowKey!==key){workflowKey=key;workflow=null;graphNodes.textContent=tr('renderWait');try{const response=await fetch('/api/render/workflow?'+new URLSearchParams({id:currentRun.id,shot:currentJob.shotId}));if(!response.ok)throw Error();const value=await response.json();if(workflowKey!==key)return;workflow=value;}catch{if(workflowKey===key){workflowKey='';graphNodes.textContent=tr('monitorWorkflowUnavailable');}return;}}drawGraph();}
 function drawGraph(){if(!workflow)return;graphNodes.replaceChildren();for(const[id,n]of Object.entries(workflow.prompt||{})){const card=node('div'),title=node('strong','#'+id+' · '+n.class_type);card.className='render-monitor-node'+(String(currentRun.live?.node)===id?' is-active':'');card.append(title);const links=Object.entries(n.inputs||{}).filter(([,v])=>Array.isArray(v)&&typeof v[0]==='string').map(([name,v])=>name+' ← #'+v[0]);if(links.length)card.append(node('p',links.join(' · ')));graphNodes.append(card);}const h3=Object.values(workflow.prompt||{}).find(n=>n.class_type==='MiniMaxH3ImageToVideo');promptText.textContent=typeof h3?.inputs?.prompt==='string'?h3.inputs.prompt:tr('monitorWorkflowUnavailable');}
 function update(run){currentRun=run;const active=run?.jobs.find(j=>['submitting','queued','running','cancelling'].includes(j.state));currentJob=active||run?.jobs.find(j=>['failed','unknown','cancelled'].includes(j.state))||run?.jobs.filter(j=>j.state==='complete').at(-1)||run?.jobs.find(j=>j.state==='planned')||run?.jobs.at(-1);if(!currentJob){section.hidden=true;float.hidden=true;return;}section.hidden=false;const j=currentJob,live=run.live?.shotId===j.shotId?run.live:null,isActive=!!active,final=j.state==='complete'&&j.results?.[0];
  const pending=run.autoRun&&run.jobs.some(v=>v.state==='planned');heading.textContent=tr('monitorTitle')+' · '+j.number+'/'+run.jobs.length+' · '+j.title;state.textContent=tr(isActive?'monitorRunning':pending?'monitorWaiting':j.state==='complete'?'monitorComplete':['failed','unknown','cancelled'].includes(j.state)?'monitorStopped':'monitorPrepared');
  const elapsed=j.started?Math.max(0,Math.floor(((j.finished||Date.now())-j.started)/1000)):0;timing.textContent=j.width+' × '+j.height+' · '+j.frames+' frames · '+j.seconds.toFixed(3)+' s'+(isActive?' · '+tr('monitorElapsed')+': '+Math.floor(elapsed/60)+':'+String(elapsed%60).padStart(2,'0'):'');
  stage.textContent=tr('monitorPhase_'+(j.state==='queued'?'queued':isActive?live?.phase||'waiting':j.state==='complete'?'complete':'ready'))+(live?.nodeType?' · '+live.nodeType+' #'+live.node:'');
  if(isActive&&live?.total){progress.max=live.total;progress.value=live.step;progress.hidden=false;stage.textContent+=' · '+tr('monitorStep')+' '+live.step+'/'+live.total;}else{progress.hidden=!isActive;progress.removeAttribute?.('value');}
  const since=live?.updated?Math.max(0,Math.round((Date.now()-live.updated)/1000)):null;connection.textContent=!Object.hasOwn(run,'live')?tr('monitorRestart'):isActive?(live?.connected?tr('monitorConnected')+(since!==null?' · '+tr('monitorLastSignal')+': '+since+' s':''):tr('monitorDisconnected')):tr('monitorPreviewNote');
  if(run.backendActivity?.available===false){connection.textContent=tr('monitorDisconnected');state.textContent=tr('monitorStatusUnknown');}else if(run.backendActivity?.others)connection.textContent+=' · '+tr('monitorOtherWork')+': '+run.backendActivity.others;
  originalLabel.textContent=tr('monitorStartImage');previewLabel.textContent=tr('monitorPreview');large.textContent=tr('monitorLarge');close.textContent=tr('monitorClose');download.textContent=tr('monitorWorkflow');graphTitle.textContent=tr('monitorGraph');promptTitle.textContent=tr('renderActualPrompt');pause.textContent=tr('renderPause');stop.textContent=tr('renderCancel');pause.disabled=stop.disabled=!(isActive||pending);
  const imageURL='/api/render/start-image?'+new URLSearchParams({id:run.id,shot:j.shotId});if(reference.getAttribute?.('src')!==imageURL)reference.src=imageURL;
  const key=run.id+j.shotId+(final?'final':live?.preview?.sequence||0);if(key!==mediaKey){mediaKey=key;picture.hidden=clip.hidden=true;clip.pause?.();clip.removeAttribute?.('src');clip.muted=clip.autoplay=clip.loop=!final;if(final){clip.preload='metadata';clip.src='/api/render/media?'+new URLSearchParams({id:run.id,shot:j.shotId,index:0});clip.hidden=false;}else if(live?.preview){const url='/api/render/preview?'+new URLSearchParams({id:run.id,shot:j.shotId,v:live.preview.sequence});if(live.preview.mime==='video/mp4'){clip.src=url;clip.hidden=false;const play=clip.play?.();play?.catch?.(()=>{});}else{picture.src=url;picture.hidden=false;}}}
  if(final)previewLabel.textContent=tr('monitorFinalVideo');saved.hidden=saveVideo.hidden=!final;if(final){saved.textContent=(renderResultLocations(run).reusedShots.includes(j.shotId)?tr('renderReusedResult')+' · ':'')+tr('renderSavedLocation')+': '+[final.subfolder,final.filename].filter(Boolean).join('/');saveVideo.href=clip.src;saveVideo.download=final.filename;saveVideo.textContent=tr('renderDownloadVideo');}
  empty.hidden=!!live?.preview||!!final;empty.textContent=tr(isActive?'monitorNoPreview':'monitorNotRunning');
  float.hidden=!(isActive||pending);float.textContent=tr(isActive?'monitorRunning':'monitorWaiting')+' · '+j.number+'/'+run.jobs.length+' ↗';
  if(graph.open||prompt.open)void workflowDetails();
 }
 return {update,lost(){connection.textContent=tr('monitorDisconnected');state.textContent=tr('monitorStatusUnknown');}};
}
